add_action( 'woocommerce_product_set_stock', 'perfectpixel_stock_history_record' );
add_action( 'woocommerce_variation_set_stock', 'perfectpixel_stock_history_record' );
add_action( 'add_meta_boxes', 'perfectpixel_stock_history_box' );

function perfectpixel_stock_history_record( $product ) {
	$history   = (array) get_post_meta( $product->get_id(), '_perfectpixel_stock_history', true );
	$user      = wp_get_current_user();
	$history[] = array(
		'time' => time(),
		'qty'  => $product->get_stock_quantity(),
		'by'   => $user->exists() ? $user->display_name : '',
	);
	$history = array_slice( array_filter( $history ), -max( 1, (int) '{{stock_history_limit}}' ) );
	update_post_meta( $product->get_id(), '_perfectpixel_stock_history', $history );
}

function perfectpixel_stock_history_box() {
	add_meta_box( 'perfectpixel_stock_history', 'Ιστορικό αποθέματος', 'perfectpixel_stock_history_render', 'product', 'normal', 'low' );
}

function perfectpixel_stock_history_render( $post ) {
	$product = wc_get_product( $post->ID );
	if ( ! $product ) {
		return;
	}
	$ids = $product->is_type( 'variable' ) ? $product->get_children() : array( $product->get_id() );
	foreach ( $ids as $id ) {
		$history = array_reverse( array_filter( (array) get_post_meta( $id, '_perfectpixel_stock_history', true ) ) );
		if ( count( $ids ) > 1 ) {
			echo '<h4>' . esc_html( wc_get_product( $id ) ? wc_get_product( $id )->get_name() : '#' . $id ) . '</h4>';
		}
		if ( ! $history ) {
			echo '<p>Δεν υπάρχουν καταγεγραμμένες κινήσεις.</p>';
			continue;
		}
		echo '<table class="widefat striped"><thead><tr><th>Ημερομηνία</th><th>Απόθεμα</th><th>Χρήστης</th></tr></thead><tbody>';
		foreach ( $history as $row ) {
			printf(
				'<tr><td>%s</td><td>%s</td><td>%s</td></tr>',
				esc_html( wp_date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $row['time'] ) ),
				esc_html( (string) $row['qty'] ),
				esc_html( $row['by'] ? $row['by'] : 'Σύστημα / παραγγελία' )
			);
		}
		echo '</tbody></table>';
	}
}
